/**
 * Feature Branch Lifecycle Manager (T8).
 *
 * Runs at the top of every poll cycle, before eligibility checks and claim.
 * Creates or syncs `feature/{featureId}` on the management (workspace) repo,
 * then records `feature_branch` and `feature_branch_base_sha` in status.yaml.
 *
 * Idempotent: if the branch already exists this is a cheap ls-remote + no-op.
 * Never overwrites `feature_branch_base_sha` once it is set — the drift daemon
 * uses it as its comparison baseline.
 *
 * Running per-cycle ensures that a branch deleted mid-session (e.g. after a
 * workspace PR is merged and the branch deleted) is recreated before the next
 * claim attempt, preventing 422 "invalid base" errors on workspace PR creation.
 *
 * Git operations are performed in the management repo (workspaceRoot).
 */

import { execSync } from "node:child_process";
import { type Dirent, existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { buildGitEnv } from "../git-env.js";
import {
  featureBranchName,
  statusYamlAbsPath,
  statusYamlRelPath,
} from "../paths.js";
import { curlJson } from "../utils/curl-json.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface EnsureFeatureBranchOpts {
  /** Absolute path to the management (workspace) repo. */
  workspaceRoot: string;
  /** Feature directory ID, e.g. "autonomous-task-orchestrator". */
  featureId: string;
  /** Base branch declared for the management repo in workspace.yaml. */
  baseBranch: string;
  gitAuthorEmail: string;
  gitAuthorName: string;
  sshKeyPath?: string;
  /** When provided, opens a draft PR on first branch creation. Idempotent — skipped if status.yaml.workspace_feature_pr_url is already set. */
  githubToken?: string;
  repoOwner?: string;
  repoName?: string;
  /** When provided, sends a Slack notification when a stale draft handoff PR is promoted to ready-for-review. */
  slackWebhookUrl?: string;
  emit: (event: Record<string, unknown>) => void;
}

export interface EnsureFeatureBranchResult {
  /** The feature branch name, e.g. "feature/autonomous-task-orchestrator". */
  featureBranch: string;
  /** Whether the branch was created fresh (true) or already existed (false). */
  created: boolean;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

interface StatusYaml {
  feature_branch?: string | null;
  feature_branch_base_sha?: string | null;
  workspace_feature_pr_url?: string | null;
  handoff_pr_url?: string | null;
  feature_status?: string | null;
  [key: string]: unknown;
}

function execGit(cmd: string, env: NodeJS.ProcessEnv, cwd: string): string {
  return execSync(cmd, {
    cwd,
    env,
    encoding: "utf-8",
    stdio: "pipe",
    timeout: 60_000,
  }).trim();
}

/**
 * Returns true if `refs/heads/<branch>` exists on the remote.
 * Uses `git ls-remote --exit-code` — exit code 2 means not found.
 */
function remoteHasBranch(branch: string, env: NodeJS.ProcessEnv, cwd: string): boolean {
  try {
    execSync(`git ls-remote --exit-code origin "refs/heads/${branch}"`, {
      cwd,
      env,
      encoding: "utf-8",
      stdio: "pipe",
      timeout: 30_000,
    });
    return true;
  } catch {
    return false;
  }
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Ensure the feature branch exists and is synced with origin.
 * Updates status.yaml with `feature_branch` and `feature_branch_base_sha`
 * (writes only if unset; never overwrites `feature_branch_base_sha`).
 */
export function ensureFeatureBranch(
  opts: EnsureFeatureBranchOpts,
): EnsureFeatureBranchResult {
  const {
    workspaceRoot,
    featureId,
    baseBranch,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    githubToken,
    repoOwner,
    repoName,
    emit,
  } = opts;

  const featureBranch = featureBranchName(featureId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  // ── Step 1: Fetch origin ──────────────────────────────────────────────────
  execGit("git fetch origin", env, workspaceRoot);

  // ── Step 2: Check if feature branch exists on remote ──────────────────────
  const existsOnRemote = remoteHasBranch(featureBranch, env, workspaceRoot);

  let baseSha: string;
  let created: boolean;

  if (existsOnRemote) {
    // ── Branch already exists — checkout and sync ─────────────────────────
    try {
      // -B resets the local branch to origin's tip if it already exists locally,
      // or creates it fresh. This handles both clean and diverged local states.
      execGit(
        `git checkout -B "${featureBranch}" "origin/${featureBranch}"`,
        env,
        workspaceRoot,
      );
    } catch (checkoutErr) {
      // Checkout failed (e.g. working tree dirty — should not happen in orchestrator
      // context, but handle defensively by re-checkout from a clean base).
      emit({
        type: "feature_branch_checkout_error",
        feature_id: featureId,
        details: String(checkoutErr),
        action: "recovering_from_base",
      });
      execGit(`git checkout "${baseBranch}"`, env, workspaceRoot);
      try {
        execGit(`git branch -D "${featureBranch}"`, env, workspaceRoot);
      } catch {
        // Branch may not exist locally yet — ignore.
      }
      execGit(
        `git checkout -b "${featureBranch}" "origin/${featureBranch}"`,
        env,
        workspaceRoot,
      );
    }

    // Compute merge-base — used when status.yaml has no feature_branch_base_sha.
    // git merge-base returns the common ancestor of the feature branch and origin base.
    try {
      baseSha = execGit(
        `git merge-base "${featureBranch}" "origin/${baseBranch}"`,
        env,
        workspaceRoot,
      );
    } catch {
      // Fallback: use the first commit on the feature branch relative to base.
      baseSha = execGit(
        `git rev-parse "origin/${baseBranch}"`,
        env,
        workspaceRoot,
      );
    }

    created = false;
    emit({
      type: "feature_branch_synced",
      feature_id: featureId,
      branch: featureBranch,
    });
  } else {
    // ── Branch does not exist — create from base branch tip ───────────────
    execGit(`git checkout "${baseBranch}"`, env, workspaceRoot);
    execGit(`git pull origin "${baseBranch}"`, env, workspaceRoot);
    baseSha = execGit("git rev-parse HEAD", env, workspaceRoot);

    // Use -B (reset) instead of -b (create-only) so a stale local branch from a
    // previous failed run is reset to base-branch tip rather than causing a fatal.
    execGit(`git checkout -B "${featureBranch}"`, env, workspaceRoot);
    execGit(`git push -u origin "${featureBranch}"`, env, workspaceRoot);

    created = true;
    emit({
      type: "feature_branch_created",
      feature_id: featureId,
      branch: featureBranch,
      base_sha: baseSha,
    });
  }

  // ── Step 3: Update status.yaml (only when fields are unset) ──────────────
  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
  if (!existsSync(statusPath)) {
    emit({
      type: "feature_status_yaml_not_found",
      feature_id: featureId,
      path: statusPath,
    });
    return { featureBranch, created };
  }

  const statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;

  let changed = false;
  if (!statusYaml.feature_branch) {
    statusYaml.feature_branch = featureBranch;
    changed = true;
  }
  // Never overwrite feature_branch_base_sha — it is the drift baseline.
  if (!statusYaml.feature_branch_base_sha) {
    statusYaml.feature_branch_base_sha = baseSha;
    changed = true;
  }

  if (changed) {
    writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");

    const relPath = statusYamlRelPath(featureId);
    execGit(`git add "${relPath}"`, env, workspaceRoot);
    try {
      execGit(
        `git commit -m "chore(${featureId}): record feature branch metadata in status.yaml"`,
        env,
        workspaceRoot,
      );
      execGit(`git push origin "${featureBranch}"`, env, workspaceRoot);
    } catch (commitErr) {
      const stderr = (commitErr as { stderr?: string }).stderr ?? "";
      if (!stderr.includes("nothing to commit")) {
        throw commitErr;
      }
      // Nothing to commit — status.yaml already had correct values. Continue.
    }

    emit({
      type: "feature_branch_status_updated",
      feature_id: featureId,
      branch: featureBranch,
      fields_written: Object.keys(statusYaml).filter(
        (k) => k === "feature_branch" || k === "feature_branch_base_sha",
      ),
    });
  }

  // ── Step 4: Open draft PR on first creation (idempotent) ─────────────────
  // Backward-compat: if handoff_pr_url is set but workspace_feature_pr_url absent
  // (pre-migration feature), treat handoff_pr_url as workspace_feature_pr_url in-memory.
  if (!statusYaml.workspace_feature_pr_url && statusYaml.handoff_pr_url) {
    statusYaml.workspace_feature_pr_url = statusYaml.handoff_pr_url;
  }

  // Skip if workspace_feature_pr_url is already recorded — PR was opened on a prior run.
  if (githubToken && repoOwner && repoName && !statusYaml.workspace_feature_pr_url) {
    try {
      const createUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls`;
      const response = curlJson([
        "-s", "-X", "POST",
        "-H", `Authorization: token ${githubToken}`,
        "-H", "Accept: application/vnd.github+json",
        "-H", "Content-Type: application/json",
        "-d", JSON.stringify({
          title: `feat(${featureId}): feature branch — work in progress`,
          body: `Feature \`${featureId}\` is under development. This draft PR tracks progress on the feature branch.`,
          head: featureBranch,
          base: baseBranch,
          draft: true,
        }),
        createUrl,
      ]) as { html_url?: string };

      if (response.html_url) {
        statusYaml.workspace_feature_pr_url = response.html_url;
        writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");

        const relPath = statusYamlRelPath(featureId);
        execGit(`git add "${relPath}"`, env, workspaceRoot);
        try {
          execGit(
            `git commit -m "chore(${featureId}): record workspace feature PR URL in status.yaml"`,
            env,
            workspaceRoot,
          );
          execGit(`git push origin "${featureBranch}"`, env, workspaceRoot);
        } catch (commitErr) {
          const stderr = (commitErr as { stderr?: string }).stderr ?? "";
          if (!stderr.includes("nothing to commit")) throw commitErr;
        }

        emit({
          type: "draft_pr_opened",
          feature_id: featureId,
          pr_url: response.html_url,
        });
      }
    } catch (e) {
      // Non-fatal — draft PR is a visibility aid; don't fail the lifecycle step.
      emit({
        type: "draft_pr_skipped",
        feature_id: featureId,
        reason: String(e),
      });
    }
  } else if (!statusYaml.workspace_feature_pr_url && (!githubToken || !repoOwner || !repoName)) {
    emit({ type: "draft_pr_skipped", feature_id: featureId, reason: "no_github_token" });
  }

  return { featureBranch, created };
}

// ── Multi-feature scan ────────────────────────────────────────────────────────

export interface RunFeatureBranchLifecycleOpts {
  workspaceRoot: string;
  /** Base branch for the management repo. */
  baseBranch: string;
  gitAuthorEmail: string;
  gitAuthorName: string;
  sshKeyPath?: string;
  /** When provided, opens a draft PR on first branch creation for each feature. */
  githubToken?: string;
  repoOwner?: string;
  repoName?: string;
  /** When provided, sends a Slack notification when a stale draft handoff PR is promoted. */
  slackWebhookUrl?: string;
  emit: (event: Record<string, unknown>) => void;
}

/**
 * Scan all feature directories in the workspace and call `ensureFeatureBranch`
 * for each one that has a status.yaml. Non-throwing: errors per-feature are
 * emitted and the scan continues.
 *
 * Returns the set of feature IDs whose branch setup failed. The caller must
 * skip dispatch for any feature in this set — a task claim will open a
 * workspace PR against the feature branch, which will 422 if the branch is
 * not on origin.
 *
 * Called at the top of every poll cycle before eligibility checks and claim.
 */
export function runFeatureBranchLifecycle(
  opts: RunFeatureBranchLifecycleOpts,
): Set<string> {
  const { workspaceRoot, baseBranch, gitAuthorEmail, gitAuthorName, sshKeyPath, githubToken, repoOwner, repoName, slackWebhookUrl, emit } = opts;

  const featuresDir = join(workspaceRoot, "docs", "features");
  if (!existsSync(featuresDir)) {
    emit({ type: "feature_branch_lifecycle_no_features_dir", workspace: workspaceRoot });
    return new Set<string>();
  }

  let featureDirs: string[];
  try {
    featureDirs = readdirSync(featuresDir, { withFileTypes: true })
      .filter((e: Dirent) => e.isDirectory())
      .map((e: Dirent) => e.name);
  } catch (e) {
    emit({ type: "feature_branch_lifecycle_scan_error", workspace: workspaceRoot, details: String(e) });
    return new Set<string>();
  }

  const BRANCH_ELIGIBLE = new Set([
    "ready_for_implementation",
    "in_implementation",
    "in_handoff",
  ]);

  // Build git env once for use in the restore-to-base steps below.
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  const failedFeatureIds = new Set<string>();

  for (const featureId of featureDirs) {
    // Read status.yaml via `git show origin/<baseBranch>:...` rather than the
    // local filesystem. ensureFeatureBranch checks out the feature branch and
    // leaves the working tree there; subsequent iterations would otherwise read
    // status.yaml from that feature branch, missing features that were merged
    // to the base branch after the feature branch was cut (e.g. a newly created
    // feature whose directory doesn't exist on older feature branches).
    const relPath = `docs/features/${featureId}/status.yaml`;
    let statusYamlContent: string;
    try {
      statusYamlContent = execGit(
        `git show "origin/${baseBranch}:${relPath}"`,
        env,
        workspaceRoot,
      );
    } catch {
      // File doesn't exist on origin/baseBranch — skip this feature.
      continue;
    }

    let featureStatus: string | undefined;
    try {
      const raw = parseYaml(statusYamlContent) as { feature_status?: string };
      featureStatus = raw.feature_status;
    } catch {
      emit({ type: "feature_branch_lifecycle_skipped", feature_id: featureId, reason: "status_yaml_unreadable" });
      continue;
    }

    if (!featureStatus || !BRANCH_ELIGIBLE.has(featureStatus)) {
      emit({ type: "feature_branch_lifecycle_skipped", feature_id: featureId, reason: `feature_status=${featureStatus}` });
      continue;
    }

    try {
      ensureFeatureBranch({
        workspaceRoot,
        featureId,
        baseBranch,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        githubToken,
        repoOwner,
        repoName,
        slackWebhookUrl,
        emit,
      });
    } catch (e) {
      emit({
        type: "feature_branch_lifecycle_error",
        feature_id: featureId,
        workspace: workspaceRoot,
        details: String(e),
      });
      // Mark as failed — dispatch must not claim tasks for this feature until
      // all feature branches exist on origin.
      failedFeatureIds.add(featureId);
    } finally {
      // Restore to base branch after each feature — ensureFeatureBranch leaves
      // the working tree on the feature branch. Without this restore the next
      // iteration's git show would still work (it reads from origin), but the
      // working tree would remain on the feature branch, which confuses any
      // filesystem reads inside ensureFeatureBranch itself.
      try { execGit(`git checkout "${baseBranch}"`, env, workspaceRoot); } catch { /* best-effort */ }
    }
  }

  // Final restore to base branch — ensures findEligibleTasks (which reads
  // task files from the local filesystem) always scans the base-branch content,
  // not whichever feature branch was last checked out by ensureFeatureBranch.
  // checkout -B resets the local branch to origin tip without a hard reset.
  try {
    execGit(`git checkout -B "${baseBranch}" "origin/${baseBranch}"`, env, workspaceRoot);
  } catch { /* best-effort */ }

  return failedFeatureIds;
}

