/**
 * Feature Notification Watcher — detects feature-level lifecycle events and
 * routes them to the NotificationPort.
 *
 * Called once per poll cycle (after syncWorkspaces). Tracks per-process state
 * so it can distinguish the "first active poll" (feature_start) from a
 * "status change" (feature_summary_changed).
 *
 * Guarantees:
 * - Calls postFeatureMessage('feature_start', ...) exactly once per
 *   process run per feature the first time it is seen in an active state.
 *   ensureFeatureThread is idempotent via Redis so restart re-entry is safe.
 * - Calls postFeatureMessage('feature_summary_changed', ...) only when
 *   feature_status or next_action changes after the initial start.
 * - Never calls the port on a routine poll with no change.
 * - Never calls postFeatureMessage for task-only transitions (it only reads
 *   feature-level fields from status.yaml).
 * - Skips terminal features (done, cancelled).
 */

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { execSync } from "node:child_process";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import type { NotificationPort } from "../notifications/notification.port.js";
import type { FeatureContext } from "../notifications/notification.types.js";
import { featuresRoot, featureBranchName, statusYamlRelPath, TASKS_DIR } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface FeatureNotificationState {
  /** Features for which feature_start has been dispatched in this process run. */
  startedFeatures: Set<string>;
  /** Last seen compound status key per featureId: "<feature_status>|<next_action>". */
  lastStatusKeys: Map<string, string>;
}

export function createFeatureNotificationState(): FeatureNotificationState {
  return {
    startedFeatures: new Set(),
    lastStatusKeys: new Map(),
  };
}

export interface RunFeatureNotificationOpts {
  workspaceRoot: string;
  workspaceId: string;
  notificationPort: NotificationPort;
  state: FeatureNotificationState;
  gitAuthorEmail?: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

// ── Status YAML shape ──────────────────────────────────────────────────────────

interface StatusYaml {
  title?: string;
  feature_status?: string;
  next_action?: string | null;
  handoff_pr_url?: string | null;
  workspace_feature_pr_url?: string | null;
  feature_branch?: string | null;
  history?: Array<{ at?: string }>;
  [key: string]: unknown;
}

// ── Internal constants ────────────────────────────────────────────────────────

const ACTIVE_STATUSES = new Set([
  "ready_for_implementation",
  "in_implementation",
]);

const TERMINAL_STATUSES = new Set(["done", "cancelled"]);

// The watcher handles feature_summary_changed for transitions to in_handoff
// as well (the handoff_submitted trigger is fired separately in
// check-feature-tasks-done). This avoids a notification gap for features
// that transition in_handoff without the watcher having fired handoff_submitted.
const WATCHED_STATUSES = new Set([
  "ready_for_implementation",
  "in_implementation",
  "in_handoff",
]);

// ── Helpers ───────────────────────────────────────────────────────────────────

function listFeatureIds(workspaceRoot: string): string[] {
  const root = featuresRoot(workspaceRoot);
  if (!existsSync(root)) return [];
  try {
    return readdirSync(root, { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => e.name);
  } catch {
    return [];
  }
}

/**
 * Read status.yaml for a feature from origin/<featureBranch>, falling back to
 * origin/baseBranch then local FS. Returns null when unreadable.
 */
function readStatusYaml(
  workspaceRoot: string,
  featureId: string,
  env: NodeJS.ProcessEnv,
): StatusYaml | null {
  const featureBranch = featureBranchName(featureId);
  const relPath = statusYamlRelPath(featureId);

  for (const ref of [`origin/${featureBranch}`, "origin/main"]) {
    try {
      const raw = execSync(
        `git -C "${workspaceRoot}" show "${ref}:${relPath}"`,
        { encoding: "utf-8", stdio: "pipe" },
      );
      const parsed = parseYaml(raw) as StatusYaml | undefined;
      if (parsed && typeof parsed === "object") return parsed;
    } catch { /* try next ref */ }
  }

  const absPath = join(workspaceRoot, "docs", "features", featureId, "status.yaml");
  if (!existsSync(absPath)) return null;
  try {
    return parseYaml(readFileSync(absPath, "utf-8")) as StatusYaml;
  } catch {
    return null;
  }
}

/**
 * Count task YAML files for a feature from origin/<featureBranch>.
 * Returns 0 when unreachable.
 */
function countTaskFiles(
  workspaceRoot: string,
  featureId: string,
  env: NodeJS.ProcessEnv,
): number {
  const featureBranch = featureBranchName(featureId);
  const tasksRelDir = join("docs", "features", featureId, TASKS_DIR);
  try {
    const listing = execSync(
      `git -C "${workspaceRoot}" ls-tree --name-only "origin/${featureBranch}" "${tasksRelDir}/"`,
      { encoding: "utf-8", stdio: "pipe" },
    );
    return listing
      .split("\n")
      .map((f) => f.trim())
      .filter((f) => /T\d+[a-z]*\.yaml$/.test(f)).length;
  } catch {
    // Feature branch may not exist yet — fall back to local FS count
    const dir = join(workspaceRoot, "docs", "features", featureId, TASKS_DIR);
    if (!existsSync(dir)) return 0;
    try {
      return readdirSync(dir).filter((f) => /T\d+[a-z]*\.yaml$/.test(f)).length;
    } catch {
      return 0;
    }
  }
}

function buildFeatureContext(
  statusYaml: StatusYaml,
  totalTaskCount: number,
): FeatureContext {
  const history = statusYaml.history ?? [];
  const lastEntry = history[history.length - 1];
  return {
    title: statusYaml.title ?? "Untitled feature",
    status: statusYaml.feature_status ?? "unknown",
    nextAction: statusYaml.next_action ?? null,
    handoff: statusYaml.handoff_pr_url ?? null,
    featurePr: statusYaml.workspace_feature_pr_url ?? null,
    totalTaskCount,
    lastUpdatedAt: lastEntry?.at ?? null,
  };
}

/** Compound status key that captures all feature-level fields we watch. */
function statusKey(s: StatusYaml): string {
  return `${s.feature_status ?? ""}|${s.next_action ?? ""}`;
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * One poll cycle of feature notification detection.
 *
 * Non-throwing: errors per-feature are emitted and the scan continues.
 */
export async function runFeatureNotificationStep(
  opts: RunFeatureNotificationOpts,
): Promise<void> {
  const {
    workspaceRoot,
    workspaceId,
    notificationPort,
    state,
    gitAuthorEmail = "coder@workflow",
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    emit,
  } = opts;

  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  const featureIds = listFeatureIds(workspaceRoot);

  for (const featureId of featureIds) {
    try {
      const statusYaml = readStatusYaml(workspaceRoot, featureId, env);
      if (!statusYaml) continue;

      const featureStatus = statusYaml.feature_status ?? "";

      // Skip terminal features entirely.
      if (TERMINAL_STATUSES.has(featureStatus)) continue;

      // Only watch features in known active states.
      if (!WATCHED_STATUSES.has(featureStatus)) continue;

      const totalTaskCount = countTaskFiles(workspaceRoot, featureId, env);
      const context = buildFeatureContext(statusYaml, totalTaskCount);
      const currentKey = statusKey(statusYaml);

      if (!state.startedFeatures.has(featureId)) {
        // First time we observe this feature as active — send feature_start.
        // Only do this for truly active (not in_handoff) features so that a
        // process restart after handoff doesn't re-trigger start.
        if (ACTIVE_STATUSES.has(featureStatus)) {
          emit({ type: "feature_notification_start", feature_id: featureId });
          await notificationPort.postFeatureMessage(featureId, "feature_start", context);
          state.startedFeatures.add(featureId);
          state.lastStatusKeys.set(featureId, currentKey);
        } else {
          // in_handoff and not previously started — still record as seen.
          state.startedFeatures.add(featureId);
          state.lastStatusKeys.set(featureId, currentKey);
        }
      } else {
        // Feature already seen — check if status changed.
        const lastKey = state.lastStatusKeys.get(featureId);
        if (lastKey !== currentKey) {
          emit({
            type: "feature_notification_summary_changed",
            feature_id: featureId,
            prev_status: lastKey ?? "",
            new_status: currentKey,
          });
          await notificationPort.postFeatureMessage(
            featureId,
            "feature_summary_changed",
            context,
          );
          state.lastStatusKeys.set(featureId, currentKey);
        }
        // No change — routine poll, no port call.
      }
    } catch (e) {
      emit({
        type: "feature_notification_watcher_error",
        feature_id: featureId,
        details: String(e),
      });
    }
  }
}

