/**
 * Feature-Tasks-Done checker — polls for features where all tasks are done
 * and fires the Handoff Trigger.
 *
 * Runs on every poll cycle (after handleMergedPrs). Reads task YAMLs from
 * origin/<featureBranch> — the authoritative multi-task view — rather than
 * from the local FS of a single task branch.
 *
 * A feature is eligible when:
 *   - feature_status is not already "in_handoff", "done", or "cancelled"
 *   - handoff_pr_url is null (idempotent guard)
 *   - every T*.yaml on origin/<featureBranch> has status "done" or "cancelled"
 *   - at least one task is "done" (pure-cancelled features are skipped)
 *
 * This replaces the inline checkAllTasksDone + fireHandoffTrigger calls that
 * previously lived inside handle-merged-prs and dispatch-review-result, both
 * of which read from the local task-branch FS and could fire too early when
 * sibling task YAMLs were not yet present on that branch.
 */

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { execSync } from "node:child_process";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import type { Task } from "../types/task.js";
import { featuresRoot, featureBranchName, statusYamlRelPath, TASKS_DIR } from "../paths.js";
import { buildGitEnv } from "../git-env.js";
import { fireHandoffTrigger } from "../handoff/handoff-trigger.js";
import { parseManagementRepoCoords } from "../config/workspace-config.js";
import type { NotificationPort } from "../notifications/notification.port.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface CheckFeatureTasksDoneOpts {
  workspaceRoot: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  /** When provided, sends handoff_submitted notification after a successful handoff trigger. */
  notificationPort?: NotificationPort;
  workspaceId?: string;
  emit: (event: Record<string, unknown>) => void;
}

interface StatusYaml {
  title?: string;
  feature_status?: string;
  feature_branch?: string | null;
  handoff_pr_url?: string | null;
  workspace_feature_pr_url?: string | null;
  next_action?: string | null;
  history?: Array<{ at?: string }>;
  [key: string]: unknown;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function listFeatureIds(workspaceRoot: string): string[] {
  const docsPath = featuresRoot(workspaceRoot);
  if (!existsSync(docsPath)) return [];
  try {
    return readdirSync(docsPath, { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => e.name);
  } catch {
    return [];
  }
}

/**
 * Read status.yaml for a feature from origin/<featureBranch> via git show.
 * Falls back to origin/main and then local FS for pre-feature-branch features.
 */
function readStatusFromBranch(
  workspaceRoot: string,
  featureId: string,
  featureBranch: string,
  env: NodeJS.ProcessEnv,
): StatusYaml {
  const relPath = statusYamlRelPath(featureId);

  // Prefer the feature branch — this is where orchestrator writes in_handoff.
  for (const ref of [`origin/${featureBranch}`, "origin/main"]) {
    try {
      const raw = execSync(
        `git -C "${workspaceRoot}" show "${ref}:${relPath}"`,
        { encoding: "utf-8", stdio: "pipe" },
      );
      const parsed = parseYaml(raw) as StatusYaml | undefined;
      if (parsed && typeof parsed === "object") return parsed;
    } catch { /* try next ref */ }
  }

  // Local FS fallback.
  const absPath = join(workspaceRoot, "docs", "features", featureId, "status.yaml");
  if (!existsSync(absPath)) return {};
  try {
    return parseYaml(readFileSync(absPath, "utf-8")) as StatusYaml;
  } catch {
    return {};
  }
}

/**
 * Read all T*.yaml files for a feature from origin/<featureBranch>.
 * Returns an empty array when the feature branch or tasks dir is absent.
 */
function readTasksFromBranch(
  workspaceRoot: string,
  featureId: string,
  featureBranch: string,
  env: NodeJS.ProcessEnv,
): Task[] {
  const tasks: Task[] = [];

  // List task files via git ls-tree so we don't need a local checkout.
  const tasksRelDir = join("docs", "features", featureId, TASKS_DIR);
  let listing: string;
  try {
    listing = execSync(
      `git -C "${workspaceRoot}" ls-tree --name-only "origin/${featureBranch}" "${tasksRelDir}/"`,
      { encoding: "utf-8", stdio: "pipe" },
    );
  } catch {
    return [];
  }

  const taskFiles = listing
    .split("\n")
    .map((f) => f.trim())
    .filter((f) => /T\d+[a-z]*\.yaml$/.test(f));

  for (const relPath of taskFiles) {
    try {
      const raw = execSync(
        `git -C "${workspaceRoot}" show "origin/${featureBranch}:${relPath}"`,
        { encoding: "utf-8", stdio: "pipe" },
      );
      tasks.push(parseYaml(raw) as Task);
    } catch { /* skip unreadable */ }
  }

  return tasks;
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Check all features in the workspace. For any feature where all tasks are
 * done/cancelled and the handoff has not yet been triggered, fire the Handoff
 * Trigger.
 *
 * Non-throwing: each feature is processed independently.
 */
export async function checkFeatureTasksDone(
  opts: CheckFeatureTasksDoneOpts,
): Promise<void> {
  const {
    workspaceRoot,
    githubToken,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    notificationPort,
    workspaceId,
    emit,
  } = opts;

  if (!githubToken) {
    emit({ type: "check_feature_tasks_done_skipped", reason: "no_github_token" });
    return;
  }

  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  // Fetch once so all git show calls see the latest remote state.
  try {
    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
  } catch (e) {
    emit({ type: "check_feature_tasks_done_fetch_failed", details: String(e) });
    return;
  }

  const featureIds = listFeatureIds(workspaceRoot);

  for (const featureId of featureIds) {
    try {
      const featureBranch = featureBranchName(featureId);
      const statusYaml = readStatusFromBranch(workspaceRoot, featureId, featureBranch, env);

      // Skip terminal or already-triggered features.
      const skip = ["in_handoff", "done", "cancelled"];
      if (skip.includes(statusYaml.feature_status ?? "")) continue;
      if (statusYaml.handoff_pr_url) continue;

      const tasks = readTasksFromBranch(workspaceRoot, featureId, featureBranch, env);
      if (tasks.length === 0) continue;

      const hasDone = tasks.some((t) => t.status === "done");
      const allTerminal = tasks.every(
        (t) => t.status === "done" || t.status === "cancelled",
      );

      if (!hasDone || !allTerminal) continue;

      emit({ type: "all_tasks_done", feature_id: featureId });

      try {
        const { owner, repo, baseBranch } = parseManagementRepoCoords(workspaceRoot);
        const result = await fireHandoffTrigger({
          workspaceRoot,
          featureId,
          baseBranch,
          githubToken,
          repoOwner: owner,
          repoName: repo,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          emit,
        });
        if (result.error) {
          emit({ type: "handoff_trigger_failed", feature_id: featureId, details: result.error });
        } else if (notificationPort) {
          // Send handoff_submitted notification now that status.yaml has been
          // updated to in_handoff and the handoff PR URL is set.
          try {
            const history = statusYaml.history ?? [];
            const lastEntry = history[history.length - 1];
            await notificationPort.postFeatureMessage(featureId, "handoff_submitted", {
              title: statusYaml.title ?? "Untitled feature",
              status: "in_handoff",
              handoff: result.prUrl ?? null,
              featurePr: statusYaml.workspace_feature_pr_url ?? null,
              totalTaskCount: tasks.length,
              lastUpdatedAt: lastEntry?.at ?? null,
            });
          } catch (notifyErr) {
            emit({
              type: "handoff_submitted_notification_failed",
              feature_id: featureId,
              details: String(notifyErr),
            });
          }
        }
      } catch (e) {
        emit({ type: "handoff_trigger_failed", feature_id: featureId, details: String(e) });
      }
    } catch (e) {
      emit({ type: "check_feature_tasks_done_error", feature_id: featureId, details: String(e) });
    }
  }
}

