    taskRepoUrl,
    taskRepoBranch: taskBranch,
    taskBaseBranch,
    taskRepoBaseBranch,
    executorWorkdir: join(workspacesRoot, `exec-${handle}`),
    mgmtRepoUrl,
    resultPath,
    budgetTokens: config.budget.max_tokens_per_task,
    implementationModel,
    sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
    githubToken,
    callbackUrl,
    nonce,
    // Broker `HandleKind` is decoupled from the orchestrator-internal `kind`
    // concept used for briefing routing. The reap loop branches:
    //   - kind="impl"      → dispatchExecutorResult (writes terminal_status to YAML)
