    await postTaskSlack({
      event: event.type,
      featureId: event.featureId,
      taskId: event.taskId,
      taskTitle: event.taskTitle,
      prUrl: event.prUrl,
      blockedReason: event.blockedReason,
      webhookUrl: this.webhookUrl,
    });
  }
}

